/* SPDX-License-Identifier: GPL-3.0-only
 * Actual offline browser acceptance. Requires Playwright plus installed Chrome.
 * Inputs are generated by tests/web_cover_fixtures.py, never a user's artwork.
 */
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { createHash } = require('node:crypto');
const { chromium } = require('./browser/node_modules/playwright');
const root = path.resolve(__dirname, '..');
const evidence = path.resolve(process.env.SAROO_WEB_UI_EVIDENCE || path.join(root, 'tests/build/web-cover-browser'));

(async () => {
  await fs.mkdir(evidence, { recursive: true });
  const cover = await import(pathToFileURL(path.join(root, 'tools/covertool/web/src/cover-codec.mjs')));
  const browser = await chromium.launch({ channel: process.env.SAROO_BROWSER_CHANNEL || 'chrome', headless: true });
  const checks = [], errors = [], requests = [];
  const report = { html_sha256: createHash('sha256').update(await fs.readFile(path.join(root,'tools/covertool/web/index.html'))).digest('hex'), browser: browser.version(), platform: `${process.platform}/${process.arch}`, checks, errors, requests, hardware: false };
  async function check(name, fn) { await fn(); checks.push({ name, passed: true }); console.log('PASS', name); }
  try {
    const context = await browser.newContext({ viewport: { width: 1200, height: 950 }, locale: 'en-US', offline: true, acceptDownloads: true });
    const page = await context.newPage();
    page.on('pageerror', error => errors.push(error.message));
    page.on('console', entry => { if (entry.type() === 'error') errors.push(entry.text()); });
    page.on('request', request => { if (/^https?:/.test(request.url())) requests.push(request.url()); });
    page.setDefaultTimeout(15000);
    const idle = () => page.waitForFunction(() => !document.getElementById('open').disabled);
    const fixture = name => path.join(evidence, name);
    async function pick(button, files, target=page) { const event=target.waitForEvent('filechooser'); await target.locator(button).click(); await (await event).setFiles(files); }
    const accept = () => page.once('dialog', dialog => dialog.accept());
    const dismiss = () => page.once('dialog', dialog => dialog.dismiss());
    async function download(button, name) {
      const event = page.waitForEvent('download'); await page.locator(button).click();
      const item = await event; await item.saveAs(fixture(name));
      assert.equal(await item.failure(), null); return new Uint8Array(await fs.readFile(fixture(name)));
    }
    async function exportLibrary(name) {
      await page.locator('#export').click(); await idle();
      await page.locator('#library-download').waitFor({ state: 'visible' }); return download('#download', name);
    }
    await check('standalone file starts offline and opens an independently generated library', async () => {
      await page.goto(pathToFileURL(path.join(root, 'tools/covertool/web/index.html')).href); await idle();
      await pick('#open', fixture('library.bin')); await idle();
      await page.waitForFunction(() => document.querySelectorAll('#grid .card').length === 24);
      assert.match(await page.locator('#library-state').innerText(), /^50 \/ 16,384/);
      await page.screenshot({ path: fixture('library.png') });
    });
    await check('pages and filtering retain all records without creating hidden canvases', async () => {
      await page.locator('#next').click(); await page.waitForFunction(() => document.querySelector('#grid .serial').textContent === 'GAME00000024');
      await page.locator('#next').click(); await page.waitForFunction(() => document.querySelectorAll('#grid .card').length === 2);
      await page.locator('#search').fill('GAME00000049'); await page.waitForFunction(() => document.querySelectorAll('#grid .card').length === 1);
      assert.equal(await page.locator('#grid canvas').count(), 1);
      await page.locator('#search').fill(''); await page.waitForFunction(() => document.querySelectorAll('#grid .card').length === 24);
    });
    await check('untouched browser download preserves complete source bytes', async () => {
      assert.deepEqual(await exportLibrary('untouched.bin'), new Uint8Array(await fs.readFile(fixture('library.bin'))));
    });
    await check('explicit compaction removes only unused space from an untouched library', async () => {
      await page.locator('#compact').check();
      const packed = await exportLibrary('compacted.bin');
      const original = await cover.CoverLibrary.open(new Blob([await fs.readFile(fixture('library.bin'))]));
      assert.deepEqual(packed, new Uint8Array(await (await original.export({ repack: true })).arrayBuffer()));
      await page.locator('#compact').uncheck(); assert.equal(await page.locator('#library-download').isVisible(), false);
    });
    let edited;
    await check('twelve-byte serial edit preserves image and reserved bytes', async () => {
      await page.locator('#grid .card').first().click(); await page.locator('#editor').waitFor({ state: 'visible' });
      await page.locator('#serial').fill('ABCDEFGHIJKL'); await page.locator('#hash').fill('FEDC1234');
      await page.screenshot({ path: fixture('editor.png') });
      await page.locator('#save-editor').click(); await page.locator('#editor').waitFor({ state: 'hidden' }); await idle();
      edited = await exportLibrary('edited.bin');
      const before = await cover.CoverLibrary.open(new Blob([await fs.readFile(fixture('library.bin'))]));
      const after = await cover.CoverLibrary.open(new Blob([edited]));
      assert.equal(after.meta(0).serial, 'ABCDEFGHIJKL'); assert.equal(after.meta(0).hash, 0xFEDC1234);
      assert.deepEqual(after.image(0).data, before.image(0).data); assert.deepEqual(edited.slice(24, 32), new Uint8Array(Buffer.from('RESERVED')));
    });
    await check('dirty replacement can be canceled and failed open retains the old library', async () => {
      dismiss(); await page.locator('#new').click(); assert.match(await page.locator('#library-state').innerText(), /^50 /);
      accept(); await pick('#open', fixture('short.bin')); await idle();
      assert.match(await page.locator('#message').innerText(), /index/); assert.deepEqual(await exportLibrary('after-failed-open.bin'), edited);
    });
    await check('duplicate edit is rejected without a partial library mutation', async () => {
      await page.locator('#grid .card').nth(1).click();
      await page.locator('#serial').fill('ABCDEFGHIJKL'); await page.locator('#hash').fill('FEDC1234');
      await page.locator('#save-editor').click(); await idle();
      assert.match(await page.locator('#editor-error').innerText(), /Duplicate/);
      accept(); await page.locator('#close-editor').click(); assert.deepEqual(await exportLibrary('after-duplicate.bin'), edited);
    });
    await check('indexed import retains custom dimensions and disc header identifies it', async () => {
      await pick('#add', fixture('unidentified.bmp'));
      await page.waitForFunction(() => document.getElementById('width').value === '3' && !document.getElementById('save-editor').disabled);
      assert.equal(await page.locator('#height').inputValue(), '7');
      await pick('#read-disc', fixture('disc.bin')); await idle();
      assert.equal(await page.locator('#serial').inputValue(), 'MK-81000');
      assert.equal(await page.locator('#hash').inputValue(), cover.hex8(cover.adler32(Uint8Array.from({ length: 64 }, (_, i) => i))));
      await page.locator('#bmp').click(); await idle(); await page.locator('#image-download').waitFor({ state: 'visible' });
      const bmp = await download('#image-download-link', 'exported.bmp');
      assert.deepEqual(cover.decodeBMP8(bmp).data, cover.decodeBMP8(new Uint8Array(await fs.readFile(fixture('unidentified.bmp')))).data);
      await page.locator('#png').click(); await idle(); const png = await download('#image-download-link', 'exported.png');
      assert.deepEqual([...png.slice(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10]);
      await page.locator('#save-editor').click(); await page.locator('#editor').waitFor({ state: 'hidden' }); await idle();
      assert.match(await page.locator('#library-state').innerText(), /^51 /);
    });
    await check('generic image fit, resize and canceled edits behave in the actual browser', async () => {
      await pick('#add', fixture('cover_COLOR~11111111.png'));
      await page.waitForFunction(() => !document.getElementById('preview').hidden && !document.getElementById('save-editor').disabled);
      const border = await page.locator('#preview').evaluate(canvas => [...canvas.getContext('2d').getImageData(0, 0, 1, 1).data]);
      assert.deepEqual(border, [255, 255, 255, 255]);
      await page.locator('#size').selectOption('128x128'); await idle();
      assert.equal(await page.locator('#preview').getAttribute('height'), '128');
      await page.locator('#fit').selectOption('cover'); await idle();
      dismiss(); await page.locator('#close-editor').click(); assert.equal(await page.locator('#editor').evaluate(el => el.open), true);
      await page.locator('#save-editor').click(); await page.locator('#editor').waitFor({ state: 'hidden' }); await idle();
      assert.match(await page.locator('#library-state').innerText(), /^52 /);
    });
    await check('batch imports complete items and gives explicit review of others', async () => {
      await pick('#add', [fixture('cover_COLOR~11111111.png'), fixture('cover_BATCH~22222222.bmp'), fixture('unidentified.bmp')]);
      await page.locator('#batch-start').click(); await idle(); await page.locator('#review').waitFor({ state: 'visible' });
      assert.match(await page.locator('#library-state').innerText(), /^53 /);
      assert.equal(await page.locator('#review-items li').count(), 2);
      assert.match(await page.locator('#review-items').innerText(), /Duplicate/);
    });
    await check('delete uses the selected committed record and invalidates old export', async () => {
      await exportLibrary('before-delete.bin'); await page.locator('#grid .card').first().click();
      accept(); await page.locator('#delete').click(); await page.locator('#editor').waitFor({ state: 'hidden' }); await idle();
      assert.match(await page.locator('#library-state').innerText(), /^52 /);
      assert.equal(await page.locator('#library-download').isVisible(), false);
      const library = await cover.CoverLibrary.open(new Blob([await exportLibrary('final.bin')]));
      assert.equal(library.count, 52); assert.equal(library.meta(0).serial, 'GAME00000001');
    });
    await check('mobile viewport keeps editor controls reachable', async () => {
      await page.setViewportSize({ width: 390, height: 844 }); await page.locator('#grid .card').first().click();
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
      await page.locator('#save-editor').scrollIntoViewIfNeeded(); await page.screenshot({ path: fixture('mobile-editor.png') });
      await page.locator('#close-editor').click(); await page.setViewportSize({ width: 1200, height: 950 });
    });
    await check('no page errors or HTTP requests occurred with networking disabled', async () => { assert.deepEqual(errors, []); assert.deepEqual(requests, []); });
    await check('worker failure releases pending UI work and keeps a prepared download usable', async () => {
      const fault = await context.newPage();
      try {
        await fault.goto(pathToFileURL(path.join(root, 'tools/covertool/web/index.html')).href);
        await fault.waitForFunction(() => !document.getElementById('open').disabled);
        await pick('#open', fixture('library.bin'), fault);
        await fault.waitForFunction(() => !document.getElementById('open').disabled && document.querySelectorAll('#grid .card').length === 24);
        await fault.locator('#export').click(); await fault.locator('#library-download').waitFor({ state: 'visible' });
        await fault.workers()[0].evaluate(() => { setTimeout(() => { throw new Error('Deliberate fixture worker failure'); }, 0); });
        await fault.waitForFunction(() => document.getElementById('message').textContent.includes('worker stopped'));
        assert.equal(await fault.locator('#open').isDisabled(), true); assert.equal(await fault.locator('#library-download').isVisible(), true);
        const event = fault.waitForEvent('download'); await fault.locator('#download').click();
        const download = await event; await download.saveAs(fixture('after-worker-failure.bin'));
        assert.deepEqual(await fs.readFile(fixture('after-worker-failure.bin')), await fs.readFile(fixture('library.bin')));
      } finally { await fault.close(); }
    });
    report.passed = true;
  } catch (error) { report.passed = false; report.failure = error.stack; throw error; }
  finally { await fs.writeFile(fixturePath('browser-results.json'), JSON.stringify(report, null, 2) + '\n'); await browser.close(); }
  function fixturePath(name) { return path.join(evidence, name); }
})().catch(error => { console.error(error); process.exitCode = 1; });
